def article(locale, kind):
    d=TEXT[locale]; preview=kind=='preview'; group='epl-2645260-preview' if preview else 'epl-2645252-recap'
    title=d['pretitle' if preview else 'rectitle']; desc=d['predesc' if preview else 'recdesc']
    sections=d['pre' if preview else 'rec']
    sources=(
      [{'title':'Premier League fixture and match centre','url':'https://www.premierleague.com/en/match/2645260'},
       {'title':'Leeds United official preview: team news and key statistics','url':'https://www.leedsunited.com/en/news/leeds-united-vs-manchester-united-team-news-key-stats-and-everything-you-need-to-know'},
       {'title':'Prematchstats: form and head-to-head reference','url':'https://prematchstats.com/england/premier-league/leeds-united-vs-manchester-united-stats/16363886'}] if preview else
      [{'title':'Sky Sports: Liverpool v Manchester City match statistics','url':'https://www.skysports.com/football/liverpool-vs-man-city/stats/6930660155686911232'},
       {'title':'Sky Sports: Liverpool v Manchester City report','url':'https://www.skysports.com/football/liverpool-vs-man-city/6930660155686911232'},
       {'title':'Manchester City official match report','url':'https://www.mancity.com/news/mens/liverpool-v-city-premier-league-match-report-october-2026-63927325'}])
    slug=group+'-'+locale.lower()
    figure=f"https://atin84.github.io/assets/charts/{group}-{locale.lower()}.svg"
    alt=(title+'; team radar, model probability, last-five form and season comparison.' if preview else title+'; final score 0–3, incident timeline, match stats, xG checkpoints and score progression.')
    caption=(
      {'en':'Snapshot before kick-off, 18 Oct 2026. Poisson baseline is uncalibrated; not odds. Sources listed below.', 'ko':'킥오프 전 2026-10-18 기준. 포아송 기준선은 미보정 수치이며 배당률이 아닙니다. 아래 출처 참조.', 'es':'Datos previos al inicio, 18 oct 2026. Poisson no calibrado; no son cuotas.', 'ja':'2026年10月18日の試合前時点。未較正のポアソン基準で、オッズではありません。', 'pt-BR':'Retrato antes do jogo, 18 out 2026. Poisson não calibrado; não são odds.', 'fr':'Données avant le match, 18 oct. 2026. Poisson non calibré, sans valeur de cote.', 'de':'Datenstand vor Anpfiff am 18.10.2026. Unkalibrierte Poisson-Basis, keine Quote.', 'hi':'मैच से पहले 18 अक्टूबर 2026 की स्थिति। बिना-कैलिब्रेशन पोआसों आधार; यह सट्टा भाव नहीं है।'}[locale] if preview else
      {'en':'Sky Sports match data; the xG graphic compares two checkpoints, not a continuous shot-by-shot curve.', 'ko':'Sky Sports 경기 데이터. xG 그림은 두 시점 비교이며 슈팅별 연속 곡선이 아닙니다.', 'es':'Datos de Sky Sports; el xG compara dos puntos, no una curva continua por tiro.', 'ja':'Sky Sportsの試合データ。xGは2時点の比較で、連続的なシュート別曲線ではありません。', 'pt-BR':'Dados da Sky Sports; o xG compara dois pontos, não uma curva contínua por chute.', 'fr':'Données Sky Sports ; le xG compare deux points, sans courbe continue tir par tir.', 'de':'Sky-Sports-Spieldaten; xG vergleicht zwei Zeitpunkte, keine durchgehende Schusskurve.', 'hi':'Sky Sports मैच डेटा; xG दो बिंदुओं की तुलना है, हर शॉट की लगातार रेखा नहीं।'}[locale])
    pub='2026-10-18T04:38:00Z' if preview else '2026-10-11T18:30:00Z'
    return {'id':slug,'slug':slug,'platform':'github','status':'ready','title':title,'description':desc,
     'sections':[{'heading':h,'paragraphs':p,'bullets':b[0] if len(x)>2 else []} for x in sections for h,p,*b in [x]],
     'published_at':pub,'updated_at':pub,'language':locale,'league':'EPL','match_id':'2645260' if preview else '2645252','article_kind':kind,'translation_group':group,
     'labels':['Premier League','Match preview' if preview else 'Match recap','lang:'+locale], 'sources':sources,
     'figures':[{'src':figure,'alt':alt,'caption':caption}]}

def main():
    for locale in LANGS:
      for kind in ['preview','recap']:
        data=article(locale,kind)
        (ROOT/'content'/f"{data['id']}.json").write_text(json.dumps(data,ensure_ascii=False,indent=2)+'\n')
    print('created 16 localized article records')
if __name__=='__main__': main()
